function surface(input) {
    // Poincare disk model for agent taxonomy
    // u = angle (agent position), v = radius (class depth)
    const theta = input.u * 2 * Math.PI;
    const r_raw = input.v * 0.95;

    // Hyperbolic scaling: compress outer rings
    const r = Math.tanh(r_raw * 2) * 0.95;

    // Geometry state vector influence
    const delta = input.delta || 0.5;
    const kappa = input.kappa || -0.3;
    const hz = input.hz || 0.2;
    const fitness = input.fitness || 0.85;
    const attrib = input.attribution || 0.9;

    // Height encodes CHIT toggle density at this position
    const toggle_density = (delta + (1+kappa) + (1-hz) + fitness + attrib) / 5.0;
    const z = Math.sin(theta * 7) * toggle_density * 0.3 * r;

    // Position on Poincare disk
    const x = r * Math.cos(theta);
    const y = r * Math.sin(theta);

    // Color by readiness: green=healthy, yellow=partial, red=blocked
    const readiness = toggle_density;
    const red = Math.max(0, 1 - readiness * 2);
    const green = Math.min(1, readiness * 2);
    const blue = hz * 0.5;

    return {
        x: x * 5,
        y: y * 5,
        z: z,
        r: red,
        g: green,
        b: blue,
        a: 0.85
    };
}
